-- Run in the Supabase SQL editor. All tables are private to authenticated staff.
create extension if not exists "pgcrypto";
create type public.person_status as enum ('activo','inactivo','pendiente_revision');
create type public.radar_status as enum ('nuevo','revisando','descartado','aprobado');
create table public.personas (id uuid primary key default gen_random_uuid(), nombre text not null, apellidos text not null default '', nombre_completo text generated always as (trim(nombre || ' ' || apellidos)) stored, foto_url text, cargo text, empresa_organizacion text, bio text, email text unique, telefono text, linkedin_url text unique, web_url text, ubicacion text, observaciones text, estado public.person_status not null default 'pendiente_revision', radar_origen_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tags (id uuid primary key default gen_random_uuid(), nombre text not null unique, created_at timestamptz not null default now());
create table public.person_tags (persona_id uuid references public.personas(id) on delete cascade, tag_id uuid references public.tags(id) on delete cascade, primary key (persona_id, tag_id));
create table public.foros (id uuid primary key default gen_random_uuid(), nombre text not null, descripcion text, fecha date, tematica text, url text, observaciones text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.participaciones (id uuid primary key default gen_random_uuid(), persona_id uuid not null references public.personas(id) on delete cascade, foro_id uuid not null references public.foros(id) on delete cascade, rol text, tema_intervencion text, youtube_url text, comentario_interno text, valoracion smallint check (valoracion between 1 and 5), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.radar (id uuid primary key default gen_random_uuid(), nombre text not null, apellidos text not null default '', cargo text, empresa_organizacion text, bio text, linkedin_url text, web_url text, fuente text, observaciones text, estado public.radar_status not null default 'nuevo', persona_convertida_id uuid references public.personas(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.personas add constraint personas_radar_origen_fk foreign key (radar_origen_id) references public.radar(id);
create index personas_search_idx on public.personas using gin (to_tsvector('spanish', coalesce(nombre,'') || ' ' || coalesce(apellidos,'') || ' ' || coalesce(cargo,'') || ' ' || coalesce(empresa_organizacion,'')));
alter table public.personas enable row level security; alter table public.tags enable row level security; alter table public.person_tags enable row level security; alter table public.foros enable row level security; alter table public.participaciones enable row level security; alter table public.radar enable row level security;
create policy "staff only" on public.personas for all to authenticated using (true) with check (true); create policy "staff only" on public.tags for all to authenticated using (true) with check (true); create policy "staff only" on public.person_tags for all to authenticated using (true) with check (true); create policy "staff only" on public.foros for all to authenticated using (true) with check (true); create policy "staff only" on public.participaciones for all to authenticated using (true) with check (true); create policy "staff only" on public.radar for all to authenticated using (true) with check (true);
